INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (311006, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！", 311, 0.5, 8, 0, 11, 100911, 0, 0, 0);
