INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (311010, "アンナたそアンナたそ！\nおせち料理、美味しそうですぞ！\nさあ、おあがりよ！！", 311, 0.5, 8, 0, 11, 101311, 0, 0, 0);
